import React, { useState, useRef, useCallback, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import OasisLogoSVG from './OasisLogoSVG';
import { isDarkColor } from '../utils/colorUtils';

// --- Interfaces de Datos ---
interface FormData {
	format: string;
	imageUrl?: string | null;
	bgImage?: string | null;
	bgPosX?: number;
	bgPosY?: number;
	bgOpacity?: number;
	gradientStart?: string;
	gradientEnd?: string;
	blendGradient?: boolean;
	blendOpacity?: number;
	bgMode?: string;
	// Visibilidad
	showLogoIasd?: boolean;
	showLogoOasis?: boolean;
	showRrss?: boolean;
	tagVisible?: boolean;
	titleVisible?: boolean;
	title2Visible?: boolean;
	speakerVisible?: boolean;
	contentVisible?: boolean;
	dateVisible?: boolean;
	locationVisible?: boolean;
	// Contenido
	tag?: string;
	title?: string;
	subtitle?: string;
	title2?: string;
	author?: string;
	speaker?: string; // Orador / Invitado
	description?: string;
	content?: string; // Texto Bíblico / Descripción
	bibleText?: string; // Versículo bíblico
	bibleRef?: string;  // Referencia (ej: Juan 3:16)
	date?: string;
	time?: string;
	location?: string;
	// Estilos
	titleColor?: string;
	titleSize?: number;
	tagColor?: string;
	logoShadow?: number;
	logoGlow?: number;
	logoBrightness?: number;
	logoColor?: string;
	logoGotaColor?: string;
	logoGotaColor2?: string;
	bgPosX2?: number;
	bgPosY2?: number;
}

interface AnnouncementPreviewProps {
	previewRef?: any;
	formData: FormData;
	FORMATS?: any;
	currentFmt: { aspect: string };
	isMobile: boolean;
	selectedElementId: string | null;
	setSelectedElementId: (id: string | null) => void;
	setEditingElement?: any;
	shapeMode?: any;
	onCanvasTouchEnd?: any;
	selectedFieldKey?: any;
	logoOasis?: any;
	logoAdventista?: any;
	onBgPosChange?: any;
	handleElementDoubleClick: (id: string) => void;
	editingElement: string | null;
	editingValue: string;
	setEditingValue: (v: string) => void;
	commitEdit: () => void;
	set: (key: string, value: any) => void;
	assets: { iasd?: string; oasis?: string; logoOasisLetras?: string; rrss?: string; };
	rrssImage: string;
	previewBgStyle: React.CSSProperties;
	onCanvasClick: (e: React.MouseEvent) => void;
	containerWidth?: number;
	children?: React.ReactNode;
}

const getScales = (format: string, width: number) => {
	const f = width / 100; // 1cqw = 1% of width
	if (format === 'whatsapp') {
		return {
			inset: 5 * f, padding: 5 * f, iasd: 10 * f, oasis: 16 * f, gap: 3 * f,
			tag: 3.5 * f, title: 9 * f, sub: 5 * f, speaker: 4.5 * f, content: 3.8 * f, meta: 3.8 * f,
			rrssText: 4 * f, rrssIcon: 12 * f
		};
	} else if (format === 'youtube') {
		return {
			inset: 2 * f, padding: 1.5 * f, iasd: 6 * f, oasis: 10 * f, gap: 1.2 * f,
			tag: 2 * f, title: 5.5 * f, sub: 3 * f, speaker: 2.8 * f, content: 2.5 * f, meta: 2.5 * f,
			rrssText: 2.5 * f, rrssIcon: 5.5 * f
		};
	}
	return {
		// Instagram (1:1)
		inset: 4 * f, padding: 3 * f, iasd: 11 * f, oasis: 16 * f, gap: 2.5 * f,
		tag: 2.8 * f, title: 7.5 * f, sub: 4.5 * f, speaker: 4 * f, content: 3.5 * f, meta: 3.2 * f,
		rrssText: 3.5 * f, rrssIcon: 10 * f
	};
};

const AnnouncementPreview: React.FC<AnnouncementPreviewProps> = ({
	formData, currentFmt, isMobile, selectedElementId, setSelectedElementId,
	handleElementDoubleClick, editingElement, editingValue, setEditingValue,
	commitEdit, set, assets, rrssImage, previewBgStyle, onCanvasClick, 
	previewRef, containerWidth, children
}) => {

	const previewRefLocal = useRef<HTMLDivElement>(null);
	const [bgPos, setBgPos] = useState({ x: 50, y: 50 });
	const [isDragging, setIsDragging] = useState(false);
	const [cWidth, setCWidth] = useState(800); 
	const dragState = useRef({ active: false, startX: 0, startY: 0, startPosX: 50, startPosY: 50 });

	if (!formData) return null;

	const stableBgUrl = React.useMemo(() => {
		const url = formData.bgImage || formData.imageUrl;
		if (!url || !url.startsWith('http')) return url;
		return `${url}${url.includes('?') ? '&' : '?'}cors=oasis_v3`;
	}, [formData.bgImage, formData.imageUrl]);

	React.useLayoutEffect(() => {
		const updateWidth = () => {
			if (previewRefLocal.current) {
				const w = previewRefLocal.current.offsetWidth;
				if (w && w > 50) setCWidth(w);
			}
		};
		updateWidth();
		const t = setTimeout(updateWidth, 150);
		window.addEventListener('resize', updateWidth);
		return () => {
			clearTimeout(t);
			window.removeEventListener('resize', updateWidth);
		};
	}, [currentFmt, formData.format]);

	useEffect(() => {
		setBgPos({ x: formData.bgPosX || 50, y: formData.bgPosY || 50 });
	}, [formData.bgPosX, formData.bgPosY]);

	const isBackgroundDark = React.useMemo(() => {
		if (formData.bgMode === 'image' || formData.imageUrl) return true;
		const startDark = isDarkColor(formData.gradientStart || '#5b2ea6');
		const endDark = isDarkColor(formData.gradientEnd || '#16213e');
		return startDark || endDark;
	}, [formData.bgMode, formData.imageUrl, formData.gradientStart, formData.gradientEnd]);

	const onDragStart = (e: React.MouseEvent | React.TouchEvent) => {
		if (!formData.imageUrl || editingElement) return;
		const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
		const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
		dragState.current = { active: true, startX: clientX, startY: clientY, startPosX: bgPos.x, startPosY: bgPos.y };
		setIsDragging(true);
	};

	const onDragMove = useCallback((e: MouseEvent | TouchEvent) => {
		if (!dragState.current.active) return;
		const clientX = 'touches' in e ? e.touches[0].clientX : (e as MouseEvent).clientX;
		const clientY = 'touches' in e ? e.touches[0].clientY : (e as MouseEvent).clientY;
		const container = previewRefLocal.current;
		if (!container) return;
		const { width, height } = container.getBoundingClientRect();
		const dx = ((clientX - dragState.current.startX) / width) * 100;
		const dy = ((clientY - dragState.current.startY) / height) * 100;
		setBgPos({ x: Math.max(0, Math.min(100, dragState.current.startPosX + dx)), y: Math.max(0, Math.min(100, dragState.current.startPosY + dy)) });
	}, []);

	const onDragEnd = useCallback(() => {
		if (dragState.current.active) {
			set('bgPosX', bgPos.x); set('bgPosY', bgPos.y);
			dragState.current.active = false; setIsDragging(false);
		}
	}, [bgPos, set]);

	useEffect(() => {
		window.addEventListener('mousemove', onDragMove);
		window.addEventListener('mouseup', onDragEnd);
		return () => {
			window.removeEventListener('mousemove', onDragMove);
			window.removeEventListener('mouseup', onDragEnd);
		};
	}, [onDragMove, onDragEnd]);

	const fadeInProps = { initial: { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, exit: { opacity: 0, y: -10 }, transition: { duration: 0.4 } };
	const scales = React.useMemo(() => getScales(formData.format, cWidth), [formData.format, cWidth]);

	const ts = (id: string, def: any): React.CSSProperties => {
		const baseSize = (typeof def.fontSize === 'number' && !isNaN(def.fontSize)) ? def.fontSize : parseFloat(def.fontSize || 16);
		const userScale = Number(formData[`${id}Size`] || 1);
		const finalSize = Math.max(8, baseSize * userScale);
		
		return {
			fontFamily: (formData[`${id}Font`] as string) || (def.fontFamily as string),
			fontSize: `${finalSize}px`,
			color: (formData[`${id}Color`] as string) || (def.color as string),
			fontWeight: formData[`${id}Bold`] !== undefined ? (formData[`${id}Bold`] ? 'bold' : 'normal') : def.fontWeight,
			fontStyle: formData[`${id}Italic`] ? 'italic' : (def.fontStyle ?? 'normal'),
			textDecoration: formData[`${id}Underline`] ? 'underline' : 'none',
			textAlign: (formData[`${id}Align`] as React.CSSProperties['textAlign']) || (def.textAlign ?? 'center'),
			letterSpacing: formData[`${id}LetterSpacing`] !== undefined ? `${formData[`${id}LetterSpacing`]}px` : def.letterSpacing,
			lineHeight: (formData[`${id}LineHeight`] as number) || def.lineHeight,
			textShadow: (formData[`${id}Shadow`] && formData[`${id}Shadow`] !== 'none') ? (formData[`${id}Shadow`] as string) : (def.textShadow ?? 'none'),
			opacity: (formData[`${id}Opacity`] as number) || 1,
		};
	};

	const [gotaColor1, gotaColor2] = React.useMemo(() => {
		if (formData.logoColor === 'white') return ['#ffffff', '#e2e8f0'];
		if (formData.logoColor === 'black') return ['#000000', '#1a1a1a'];
		if (formData.logoColor === 'mustard') return ['#fbbf24', '#b45309'];
		if (formData.logoColor === 'custom') return [formData.logoGotaColor || '#683cde', formData.logoGotaColor2 || '#4c1d95'];
		if (isBackgroundDark) return ['#a78bfa', '#7c3aed'];
		return ['#683cde', '#000000'];
	}, [isBackgroundDark, formData.logoColor, formData.logoGotaColor, formData.logoGotaColor2]);

	return (
		<div 
			ref={(el) => { if (previewRef) previewRef.current = el; (previewRefLocal as any).current = el; }}
			style={{ 
				position: 'absolute', inset: 0, width: '100%', height: '100%', 
				display: 'flex', flexDirection: 'column', overflow: 'hidden',
				background: previewBgStyle.background 
			}}
		>
			{/* FONDO: imagen */}
			<AnimatePresence>
				{stableBgUrl && (
					<motion.img
						key="bg-image"
						data-export-id="bg-image"
						src={stableBgUrl}
						crossOrigin="anonymous"
						animate={{ objectPosition: `${bgPos.x}% ${bgPos.y}%` }}
						style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', zIndex: 1 }}
						onMouseDown={onDragStart} onClick={onCanvasClick}
					/>
				)}
			</AnimatePresence>

			{/* CAPA DE MEZCLA */}
			<div 
				data-export-id="blend-layer"
				style={{
					position: 'absolute', inset: 0, zIndex: 2, pointerEvents: 'none',
					background: (formData.blendGradient && (formData.bgImage || formData.imageUrl))
						? `linear-gradient(135deg, ${formData.gradientStart || '#5b2ea6'}, ${formData.gradientEnd || '#16213e'})`
						: 'linear-gradient(to bottom, rgba(0,0,0,0.15), rgba(0,0,0,0.85))',
					opacity: (formData.blendGradient && (formData.bgImage || formData.imageUrl))
						? (formData.blendOpacity ?? 0.5)
						: (formData.bgOpacity ?? 1),
					mixBlendMode: (formData.blendGradient && (formData.bgImage || formData.imageUrl)) ? 'multiply' : 'normal',
				}} 
			/>

			{/* MARCO ESTÉTICO */}
			<div style={{ position: 'absolute', left: scales.inset, right: scales.inset, top: scales.inset, bottom: scales.inset, border: '0.5px solid rgba(255,255,255,0.25)', borderRadius: '8px', pointerEvents: 'none', zIndex: 3 }} />

			{/* CONTENIDO PRINCIPAL */}
			<div style={{ position: 'absolute', left: scales.inset, right: scales.inset, top: scales.inset, bottom: scales.inset, padding: scales.padding, display: 'flex', flexDirection: 'column', zIndex: 5, pointerEvents: 'none', boxSizing: 'border-box' }}>
				
				{/* 1. HEADER: LOGOS */}
				<div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', width: '100%' }}>
					<AnimatePresence>
						{formData.showLogoIasd !== false && assets.iasd && (
							<motion.img key="logo-iasd" {...fadeInProps} src={assets.iasd} crossOrigin="anonymous" style={{ height: `${scales.iasd}px`, pointerEvents: 'auto' }} />
						)}
					</AnimatePresence>
					<AnimatePresence>
						{formData.showLogoOasis !== false && (
							<motion.div key="logo-oasis" {...fadeInProps} data-logo-container="oasis" style={{ height: `${scales.oasis}px`, pointerEvents: 'auto' }}>
								<OasisLogoSVG 
									size={scales.oasis} 
									gotaColor={gotaColor1}
									gotaColor2={gotaColor2}
									familyColor="#ffffff" 
									flameColor="#ffffff"
									shadowIntensity={formData.logoShadow}
									glowIntensity={formData.logoGlow}
									style={{ filter: `brightness(${formData.logoBrightness || 1})` }}
								/>
							</motion.div>
						)}
					</AnimatePresence>
				</div>

				{/* 2. CENTER: TEXTS */}
				<div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', textAlign: 'center', gap: formData.format === 'youtube' ? `${scales.gap * 0.8}px` : `${scales.gap}px`, width: '100%', padding: '10px 0' }}>
					<AnimatePresence>
						{/* Etiqueta */}
						{formData.tag && formData.tagVisible !== false && (
								<motion.div key="tag" {...fadeInProps} style={{ padding: '0.4em 1.2em', borderRadius: '50px', background: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(10px)', border: '1px solid rgba(255,255,255,0.2)', pointerEvents: 'auto', ...ts('tag', { fontFamily: "'Modern Age', 'Orbitron', sans-serif", fontSize: scales.tag, color: '#fff', fontWeight: 700, letterSpacing: '0.08em', textAlign: 'center' }) }} onDoubleClick={() => handleElementDoubleClick('tag')}>
								{formData.tag}
							</motion.div>
						)}

						{/* Título */}
						{formData.titleVisible !== false && (
							<motion.div key="title" {...fadeInProps} style={{ width: '100%', margin: 0, padding: 0, pointerEvents: 'auto', display: 'block', ...ts('title', { fontFamily: "'Orbitron', sans-serif", fontSize: scales.title, color: '#fff', fontWeight: '800', lineHeight: 1.1, textShadow: '0 4px 15px rgba(0,0,0,0.6)', textAlign: 'center' }), textAlign: 'center' }} onDoubleClick={() => handleElementDoubleClick('title')}>
								{formData.title || 'TÍTULO DEL EVENTO'}
							</motion.div>
						)}

						{/* Subtítulo */}
						{formData.title2 && formData.title2Visible !== false && (
							<motion.div key="subtitle" {...fadeInProps} style={{ width: '100%', margin: 0, padding: 0, pointerEvents: 'auto', display: 'block', ...ts('title2', { fontFamily: "'Advent Pro', sans-serif", fontSize: scales.sub, color: 'rgba(255,255,255,0.9)', fontWeight: '500', lineHeight: 1.3, textAlign: 'center' }), textAlign: 'center' }} onDoubleClick={() => handleElementDoubleClick('title2')}>
								{formData.title2}
							</motion.div>
						)}

						{/* Orador */}
						{formData.speaker && formData.speakerVisible !== false && (
							<motion.div key="speaker" {...fadeInProps} style={{ width: '100%', margin: 0, padding: 0, pointerEvents: 'auto', display: 'block', textAlign: 'center' }} onDoubleClick={() => handleElementDoubleClick('speaker')}>
								<span style={{ display: 'block', ...ts('speaker', { fontFamily: "'Blacksword', 'Dancing Script', cursive", fontSize: `calc(${scales.speaker} * 1.35)`, color: '#fff', fontWeight: 700, textShadow: '0 4px 20px rgba(0,0,0,0.7)', lineHeight: 1.1, textAlign: 'center' }), textAlign: 'center' }}>{formData.speaker}</span>
							</motion.div>
						)}

						{/* Contenido / Biblia */}
						{(formData.bibleText || formData.content) && formData.contentVisible !== false && (
							<motion.div key="content" {...fadeInProps} style={{ padding: '12px 18px', borderRadius: '12px', background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(10px)', border: '1px solid rgba(255,255,255,0.1)', maxWidth: '100%', pointerEvents: 'auto', boxSizing: 'border-box', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px', ...ts('content', { fontFamily: "'Advent Sans', 'Advent Pro', sans-serif", fontSize: scales.content, color: '#eee', fontStyle: 'italic', fontWeight: 400, lineHeight: 1.4, textAlign: 'center' }) }} onDoubleClick={() => handleElementDoubleClick('content')}>
								<span>"{formData.bibleText || formData.content}"</span>
								{formData.bibleRef && (
									<span style={{ fontSize: `calc(${scales.content} * 0.85)`, fontStyle: 'normal', fontWeight: 700, color: 'rgba(255,255,255,0.75)', letterSpacing: '0.04em' }}>
										— {formData.bibleRef}
									</span>
								)}
							</motion.div>
						)}

						{/* METADATA: FECHA, HORA, LUGAR */}
						{(formData.date || formData.time || formData.location) && (
							<motion.div key="metadata" {...fadeInProps} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: `${scales.gap}px`, pointerEvents: 'auto' }}>
								
								{/* Fila superior: Fecha y Hora */}
								{(formData.date || formData.time) && (
									<div style={{ display: 'flex', gap: '8px', flexWrap: 'nowrap', justifyContent: 'center', alignItems: 'center', width: '100%' }}>
										{formData.date && formData.dateVisible !== false && (
											<span onDoubleClick={() => handleElementDoubleClick('date')} style={{ display: 'flex', alignItems: 'center', gap: '0.4em', padding: '0.35em 0.8em', borderRadius: '50px', background: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.25)', ...ts('date', { fontFamily: "'Modern Age', 'Orbitron', sans-serif", fontSize: scales.meta, color: '#fff', fontWeight: 600, letterSpacing: '0.05em' }), whiteSpace: 'nowrap' }}>
												<svg viewBox="0 0 16 16" width="1.1em" height="1.1em" style={{ minWidth: '1.1em' }} fill="currentColor"><path d="M14 0H2a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2zM1 3.857C1 3.384 1.448 3 2 3h12c.552 0 1 .384 1 .857v10.286c0 .473-.448.857-1 .857H2c-.552 0-1-.384-1-.857V3.857z"/><path d="M6.5 7a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm3 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm3 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm-9 3a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm3 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm3 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm3 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm-9 3a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm3 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm3 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2z"/></svg> <span style={{ marginLeft: '4px' }}>{formData.date}</span>
											</span>
										)}
										{formData.time && (
											<span onDoubleClick={() => handleElementDoubleClick('time')} style={{ display: 'flex', alignItems: 'center', gap: '0.4em', padding: '0.35em 0.8em', borderRadius: '50px', background: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.25)', ...ts('time', { fontFamily: "'Modern Age', 'Orbitron', sans-serif", fontSize: scales.meta, color: '#fff', fontWeight: 600, letterSpacing: '0.05em' }), whiteSpace: 'nowrap' }}>
												<svg viewBox="0 0 16 16" width="1.1em" height="1.1em" style={{ minWidth: '1.1em' }} fill="currentColor"><path d="M8 3.5a.5.5 0 0 0-1 0V9a.5.5 0 0 0 .252.434l3.5 2a.5.5 0 0 0 .496-.868L8 8.71V3.5z"/><path d="M8 16A8 8 0 1 0 8 0a8 8 0 0 0 0 16zm7-8A7 7 0 1 1 1 8a7 7 0 0 1 14 0z"/></svg> <span style={{ marginLeft: '4px' }}>{formData.time}</span>
											</span>
										)}
									</div>
								)}

								{/* Fila inferior: Ubicación */}
								{formData.location && formData.locationVisible !== false && (
									<span onDoubleClick={() => handleElementDoubleClick('location')} style={{ display: 'flex', alignItems: 'center', gap: '0.4em', padding: '0.35em 1.1em', borderRadius: '50px', background: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.25)', ...ts('location', { fontFamily: "'Modern Age', 'Orbitron', sans-serif", fontSize: scales.meta, color: '#fff', fontWeight: 600, letterSpacing: '0.05em' }) }}>
										<svg viewBox="0 0 16 16" width="1em" height="1em" fill="currentColor"><path d="M8 16s6-5.686 6-10A6 6 0 0 0 2 6c0 4.314 6 10 6 10zm0-7a3 3 0 1 1 0-6 3 3 0 0 1 0 6z"/></svg> {formData.location}
									</span>
								)}
							</motion.div>
						)}
					</AnimatePresence>
				</div>

				{/* 3. FOOTER: RRSS */}
				<div style={{ display: 'flex', justifyContent: 'center', alignItems: 'flex-end', width: '100%' }}>
					<AnimatePresence>
						{formData.showRrss !== false && assets.rrss && (
							<motion.div key="footer-rrss" {...fadeInProps} style={{ pointerEvents: 'auto' }}>
								<img src={assets.rrss} crossOrigin="anonymous" style={{ height: `${scales.rrssIcon}px`, display: 'block' }} />
							</motion.div>
						)}
					</AnimatePresence>
				</div>
			</div>

			{/* SHAPES / CHILDREN */}
			<div style={{ position: 'absolute', inset: 0, zIndex: 4, pointerEvents: 'none' }}>
				{children}
			</div>

			{/* EDITOR OVERLAY */}
			<AnimatePresence>
				{editingElement && (
					<motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} style={{ position: 'absolute', inset: 0, zIndex: 100, background: 'rgba(0,0,0,0.85)', backdropFilter: 'blur(10px)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
						<input autoFocus style={{ width: '80%', padding: '15px', borderRadius: '12px', textAlign: 'center', fontSize: '20px' }} value={editingValue} onChange={(e) => setEditingValue(e.target.value)} onBlur={commitEdit} onKeyDown={(e) => e.key === 'Enter' && commitEdit()} />
					</motion.div>
				)}
			</AnimatePresence>
		</div>
	);
};

export default AnnouncementPreview;